contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(
        string memory name_,
        string memory tokenURI,
        uint256 itemsRemaining,
        uint256 itemPrice,
        uint16 dailyAllowance,
        address probe
    ) public payable {
        require(itemsRemaining > 0, "itemsRemaining must be positive");

        uint256 id = c.uniqueTokensOutstanding(); if (__ESBMC_reverted()) return;

        c.createGameItem(
            name_,
            tokenURI,
            true,
            true,
            itemsRemaining,
            itemPrice,
            dailyAllowance
        ); if (__ESBMC_reverted()) return;

        assert(
            c.remainingSupply(id) == itemsRemaining &&
            c.getAllowanceRemaining(probe, id) == dailyAllowance
        );
    }
}

