pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GameItems c;

    function setUp() public {
        c = new GameItems(address(this), address(this));
    }

    function _run(string memory name_, string memory tokenURI, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance, address probe) internal {
        vm.assume(itemsRemaining > 0);
        uint256 id;
        try c.uniqueTokensOutstanding() returns (uint256 __r) { id = __r; } catch { return; }
        try c.createGameItem(
            name_,
            tokenURI,
            true,
            true,
            itemsRemaining,
            itemPrice,
            dailyAllowance
        ) {} catch { return; }
        assertTrue(c.remainingSupply(id) == itemsRemaining &&
            c.getAllowanceRemaining(probe, id) == dailyAllowance);
    }

    function testFuzz_run(string memory name_, string memory tokenURI, uint256 itemsRemaining, uint256 itemPrice, uint16 dailyAllowance, address probe) public {
        vm.assume(probe.code.length == 0 && uint160(probe) > 0xffff && probe != address(this) && probe != address(c) && probe != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && probe != 0x000000000000000000636F6e736F6c652e6c6f67 && probe != 0x4e59b44847b379578588920cA78FbF26c0B4956C && probe != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(name_, tokenURI, itemsRemaining, itemPrice, dailyAllowance, probe);
    }

    receive() external payable {}
}
